import Foundation
import XCTest
import TerminalDeckNativeCore
@testable import TerminalDeckBackend

final class BackendDeckCoreTestPortSecurityControl: BackendDeckCoreTestPortSecurityCase {
    private var readOnly: BackendDeckCoreSecurityCaller { .init(kind: .remote, tiers: [.read], deviceID: "phone-1") }
    private var acting: BackendDeckCoreSecurityCaller { .init(kind: .remote, tiers: [.read, .act], deviceID: "phone-1") }
    private func start(_ f: BackendDeckCoreTestPortSecurityRig, folder: String = "/work/api", caller: BackendDeckCoreSecurityCaller = .local) async -> BackendDeckCoreSecurityCallResult { await f.call("sessions_start", o([("cwd", .string(folder))]), .init(caller: caller)) }
    private var write: V { o([("scope", .string("settings")), ("patch", o([("appearance.density", .string("compact"))]))]) }
    private func send(_ id: String, text: String = "go") -> V { o([("sessionId", .string(id)), ("text", .string(text))]) }
    func testControlL262() async throws {
        let f = try rig(), result = await f.call("sessions_list"), rows = result.value["sessions"].elements ?? [], byID = Dictionary(uniqueKeysWithValues: rows.map { ($0["id"].string ?? "", $0["status"].string ?? "") })
        XCTAssertTrue(result.ok); XCTAssertEqual(byID.keys.sorted(), ["human-1", "human-2"]); XCTAssertEqual(byID["human-1"], "working"); XCTAssertEqual(byID["human-2"], "idle")
    }
    func testControlL276() async throws {
        let f = try rig(); f.surface.sessions = ["busy", "quiet-one", "blocked"].map { BackendDeckCoreTestPortSecuritySurface.meta($0) }
        f.surface.statuses = ["busy": o([("status", .string("working")), ("at", .number(1))]), "quiet-one": o([("status", .string("waiting")), ("at", .number(1))]), "blocked": o([("status", .string("input")), ("at", .number(1))])]
        let value = await f.call("sessions_list").value, rows = value["sessions"].elements ?? []
        XCTAssertEqual(rows.map { $0["id"].string }, ["blocked", "quiet-one", "busy"]); XCTAssertEqual(value["blocked"], .number(1))
        XCTAssertEqual(rows[1]["attention"], .string("quiet")); XCTAssertEqual(rows[1]["attentionReason"], .string("prompt-ready")); XCTAssertEqual(rows[0]["attention"], .string("blocked")); XCTAssertEqual(rows[0]["attentionReason"], .string("question-unanswered"))
    }
