        XCTAssertEqual(f.surface.starts[0]["deniedTools"], .array([.string("WebFetch"), .string("mcp__deck-control")])); XCTAssertEqual(f.surface.starts[0]["noSkills"], .bool(true))
        let sent = await f.call("sessions_start", o([("cwd", .string("/work/api")), ("provider", .string("claude")), ("blockTools", .array([.string("Bash")]))])); XCTAssertFalse(sent.ok); XCTAssertEqual(f.surface.starts.count, 1)
        let invalid = await f.call("sessions_start", o([("cwd", .string("/work/api"))]), .init(sessionLimits: o([("deniedTools", .array([.string("Bash(rm *)")]))]))); XCTAssertFalse(invalid.ok); XCTAssertEqual(f.surface.starts.count, 1)
