    private func conversation(_ count: Int) -> [V] { (0..<count).map { index in o([("id", .string("\(index % 2 == 0 ? "you" : "agent"):m\(index)")), ("role", .string(index % 2 == 0 ? "you" : "agent")), ("at", .number(Double(1000 + index))), ("text", .string("message \(index)")), ("truncated", .bool(false))]) } }
    func testControlL1082() async throws {
        let f = try rig(); f.surface.transcriptSize = Double(154 * 1024 * 1024); f.surface.transcript = conversation(10)
        let value = await f.call("sessions_transcript", o([("sessionId", .string("human-1"))])).value
        XCTAssertEqual(f.surface.transcriptReads[0].1, Double(154 * 1024 * 1024 - 256 * 1024)); XCTAssertGreaterThan(value["fromByte"].number ?? 0, 0); XCTAssertEqual(value["partial"], .bool(true))
    }
    func testControlL1101() async throws { let f = try rig(); f.surface.transcriptSize = 4000; f.surface.transcript = conversation(3); let value = await f.call("sessions_transcript", o([("sessionId", .string("human-1"))])).value; XCTAssertEqual(f.surface.transcriptReads[0].1, 0); XCTAssertEqual(value["partial"], .bool(false)); XCTAssertEqual(value["returned"], .number(3)) }
    func testControlL1115() async throws { let f = try rig(); f.surface.transcriptSize = 10_000; f.surface.transcript = conversation(50); let value = await f.call("sessions_transcript", o([("sessionId", .string("human-1"))])).value; XCTAssertEqual(value["returned"], .number(40)); XCTAssertEqual(value["partial"], .bool(true)); XCTAssertEqual(value["messages"].elements?.last?["text"], .string("message 49")) }
