    func testControlL1201() async throws { let f = try rig(budgets: .init(changes: .init(limit: 1, windowMilliseconds: 60_000))); _ = await start(f); let next = await start(f, folder: "/work/web"), read = await f.call("projects_list"); XCTAssertEqual(next.refusal, .rateLimited); XCTAssertTrue(read.ok) }
    private func tap(_ taps: BackendDeckCoreSecurityTestBox<[String]>) throws -> BackendDeckCoreSecurityToolPolicy {
